function show(){var s=steps[i];renderScene(stage,s.scene);note.textContent=s.note;codeBox.querySelectorAll('.viz-line').forEach(function(l){l.classList.toggle('is-current',+l.getAttribute('data-n')===s.line);});var cur=codeBox.querySelector('.is-current');if(cur&&codeBox.scrollHeight>codeBox.clientHeight)codeBox.scrollTop=cur.offsetTop-codeBox.clientHeight/2;count.textContent='Step '+(i+1)+' / '+steps.length;pfill.style.width=((i+1)/steps.length*100)+'%';bBack.disabled=i===0;bNext.disabled=i===steps.length-1;var last=i===steps.length-1;if(window.VS)bot.innerHTML=window.VS.mascot(last?'cheer':(s.scene.out?'wow':'think'));if(last){stop();if(!awarded&&window.VS){awarded=true;window.VS.addXP('viz',ref).then(function(res){if(res&&res.gained)window.VS.celebrate('Visualization complete!','You watched '+title+' from start to finish.','cheer',res.gained);});}}}
function delay(){return[1600,1150,800,500,260][+speed.value-1];}
